import { describe, it, expect } from "vitest";
import { decideWorkerAutoEnd, DEFAULT_AUTO_END_THRESHOLDS, type AutoEndSignals } from "@/shared/lib/fleet/workerAutoEnd";
import type { WorkerEndVerdict } from "@/shared/lib/fleet/workerEnd";

const T = DEFAULT_AUTO_END_THRESHOLDS;
const done: WorkerEndVerdict = { state: "done", summary: "2/2 complete" };
const needsAttn: WorkerEndVerdict = { state: "needs-attention", summary: "1/2 still open" };
const blocked: WorkerEndVerdict = { state: "blocked", summary: "1/2 blocked" };

const sig = (o: Partial<AutoEndSignals>): AutoEndSignals => ({
  turnOpen: false, idleMs: 0, hasOutstandingQuestion: false, verdict: done, ...o,
});

describe("decideWorkerAutoEnd", () => {
  it("never acts while the turn is open (working, even if silent)", () => {
    expect(decideWorkerAutoEnd(sig({ turnOpen: true, idleMs: 10 * T.lostQuestionMs }), T)).toBe("none");
  });

  describe("no outstanding question → close-nudge when complete", () => {
    it("nudges a complete worker to close once idle past the (shorter) close window", () => {
      expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs, verdict: done }), T)).toBe("close-nudge");
    });
    it("waits until the close window elapses", () => {
      expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs - 1, verdict: done }), T)).toBe("none");
    });
    it("does NOT nudge a worker that stopped early (needs-attention) or is blocked", () => {
      expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs, verdict: needsAttn }), T)).toBe("none");
      expect(decideWorkerAutoEnd(sig({ idleMs: 10 * T.closeNudgeMs, verdict: blocked }), T)).toBe("none");
    });
  });

  describe("outstanding question → resurface only after the (longer) lost-question wait", () => {
    it("resurfaces once idle past the lost-question window", () => {
      expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs }), T))
        .toBe("resurface-question");
    });
    it("does nothing while the director still has time to answer", () => {
      expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.lostQuestionMs - 1 }), T))
        .toBe("none");
    });
    it("never closes a worker that's waiting, even if its issues read complete", () => {
      // Past the SHORTER close window but with a question outstanding → resurface path only, never close.
      expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.closeNudgeMs, verdict: done }), T))
        .toBe("none");
    });
  });

  it("uses a longer wait for lost questions than for the close-nudge", () => {
    expect(T.lostQuestionMs).toBeGreaterThan(T.closeNudgeMs);
  });
});
describe("the pane the user is IN is never ended under them", () => {
  // "Idle" measures the AGENT being between turns. Reading a worker's last message and composing a
  // reply is exactly that state, so a focused pane could be ended mid-sentence. The idle reaper has
  // always refused to touch the focused pane; this path never learned the rule.
  it("does not close a focused worker, however long it has rested", () => {
    expect(decideWorkerAutoEnd(sig({ focused: true, idleMs: 60 * 60_000, verdict: done }), T)).toBe("none");
  });

  it("does not resurface a focused worker's question either — that moves it somewhere else", () => {
    expect(
      decideWorkerAutoEnd(sig({ focused: true, hasOutstandingQuestion: true, idleMs: 60 * 60_000 }), T),
    ).toBe("none");
  });

  it("still closes the SAME worker once focus moves away", () => {
    expect(decideWorkerAutoEnd(sig({ focused: false, idleMs: T.closeNudgeMs, verdict: done }), T))
      .toBe("close-nudge");
  });

  it("treats an absent flag as not focused, so existing callers are unchanged", () => {
    expect(decideWorkerAutoEnd(sig({ idleMs: T.closeNudgeMs, verdict: done }), T)).toBe("close-nudge");
  });
});

describe("the close window bounds an UNWATCHED worker, and focus does the rest", () => {
  // A worker was reported ending while the user was still typing a reply. The window was briefly
  // raised, which treated the timer as the protection — it never was. No window is long enough if the
  // pane you are using can be ended at all, and every window is long enough if it cannot. The focus
  // guard makes a short window safe, so the timer is free to answer its real question: how long an
  // unwatched, finished worker should sit in the grid.
  it("a SHORT window is safe precisely because a focused pane is exempt", () => {
    const anHour = 60 * 60_000;
    expect(decideWorkerAutoEnd(sig({ focused: true, idleMs: anHour, verdict: done }), T)).toBe("none");
    expect(decideWorkerAutoEnd(sig({ focused: false, idleMs: T.closeNudgeMs, verdict: done }), T))
      .toBe("close-nudge");
  });

  it("keeps the close window strictly shorter than the lost-question window", () => {
    // Load-bearing: a waiting worker meets the close window FIRST and must answer `none` there.
    expect(T.lostQuestionMs).toBeGreaterThan(T.closeNudgeMs);
    expect(decideWorkerAutoEnd(sig({ hasOutstandingQuestion: true, idleMs: T.closeNudgeMs, verdict: done }), T))
      .toBe("none");
  });
});
